CREATE TABLE employees (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  department TEXT NOT NULL,
  salary REAL NOT NULL,
  hired_on TEXT NOT NULL,
  remote INTEGER NOT NULL DEFAULT 0
);
INSERT INTO employees (name, department, salary, hired_on)
VALUES ('Nia Patel', 'Engineering', 72000, '2025-03-01');
INSERT INTO employees (name, department, salary, hired_on, remote)
VALUES ('Omar Haddad', 'Design', 58000, '2025-04-15', 1);
SELECT * FROM employees;

CREATE TABLE notes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft'
);
INSERT INTO notes (body) VALUES ('Buy milk'), ('Call Ada');
DELETE FROM notes WHERE id = 2;
INSERT INTO notes (body) VALUES ('Ship v2');
SELECT * FROM notes;

ALTER TABLE products ADD COLUMN stock INTEGER NOT NULL DEFAULT 0;
UPDATE products SET stock = 25 WHERE id = 1;
SELECT id, name, stock FROM products WHERE id <= 2;

CREATE TABLE temp_list (value TEXT);
DROP TABLE temp_list;
SELECT name FROM sqlite_master WHERE type = 'table';

CREATE TABLE books (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  author TEXT NOT NULL DEFAULT 'Unknown',
  pages INTEGER
);

INSERT INTO books (title, pages) VALUES ('SQL in a weekend', 180);
SELECT * FROM books;
